import networkx as nx
import json
import os
import pandas as pd
from typing import Dict, List


def search_algorithm(src, dsts, G, num_partitions):
    """Broadcast via the best of several Steiner-tree heuristics.

    Builds multiple candidate broadcast trees that share trunk edges:
    (1) greedy cheapest-attachment Steiner heuristic,
    (2) Kou-Markowsky metric-closure MST expansion (2-approximation),
    then scores each tree by the sum of per-dst path costs and keeps the
    cheapest. Per-dst edge lists are reused across all partitions to avoid
    redundant transfers."""
    h = G.copy()
    h.remove_edges_from(list(h.in_edges(src)) + list(nx.selfloop_edges(h)))
    bc_topology = BroadCastTopology(src, dsts, num_partitions)

    def ecost(data):
        c = data.get("cost") if isinstance(data, dict) else None
        return c if c is not None else float("inf")

    # ---- Dijkstra cache over the full graph ----
    dist_cache = {}

    def sp_from(node):
        if node not in dist_cache:
            dist, paths = nx.single_source_dijkstra(h, node, weight="cost")
            dist_cache[node] = (dist, paths)
        return dist_cache[node]

    def add_path(tree, tree_nodes, path):
        for i in range(len(path) - 1):
            s, t = path[i], path[i + 1]
            if not tree.has_edge(s, t):
                tree.add_edge(s, t, data=G[s][t])
            tree_nodes.update([s, t])

    # ---- Candidate 1: greedy cheapest-attachment Steiner heuristic ----
    def build_greedy():
        tree_nodes, tree, remaining = {src}, nx.DiGraph(), set(dsts)
        while remaining:
            best = None
            for dst in remaining:
                for node in tree_nodes:
                    dist, paths = sp_from(node)
                    if dst in dist and (best is None or dist[dst] < best[0]):
                        best = (dist[dst], node, paths[dst])
            if best is None:
                dist, paths = sp_from(src)
                dst = next(iter(remaining))
                if dst not in dist:
                    remaining.discard(dst)
                    continue
                best = (dist[dst], src, paths[dst])
            _, _, path = best
            add_path(tree, tree_nodes, path)
            remaining.discard(path[-1])
        return tree

    # ---- Candidate 2: metric-closure MST (Kou-Markowsky) ----
    def build_closure_mst():
        terminals = [src] + list(dsts)
        closure = nx.Graph()
        for a in terminals:
            dist, paths = sp_from(a)
            for b in terminals:
                if a != b and b in dist:
                    if closure.has_edge(a, b):
                        if dist[b] < closure[a][b]["w"]:
                            closure[a][b]["w"] = dist[b]
                            closure[a][b]["path"] = paths[b]
                    else:
                        closure.add_edge(a, b, w=dist[b], path=paths[b])
        tree, tree_nodes = nx.DiGraph(), {src}
        if closure.number_of_edges() == 0:
            return tree
        mst = nx.minimum_spanning_tree(closure, weight="w")
        # expand MST edges from src outward (BFS over MST)
        seen, queue = {src}, [src]
        while queue:
            u = queue.pop(0)
            for v in mst.neighbors(u):
                if v in seen:
                    continue
                seen.add(v)
                queue.append(v)
                d1, p1 = sp_from(u)
                d2, p2 = sp_from(v)
                if v in d1 and (u not in d2 or d1[v] <= d2[u]):
                    add_path(tree, tree_nodes, p1[v])
                elif u in d2:
                    add_path(tree, tree_nodes, p2[u])
        return tree

    # ---- Score a tree: sum of per-dst cheapest path costs (fallback direct) ----
    direct_dist, direct_paths = sp_from(src)

    def dst_paths(tree):
        result = {}
        for dst in dsts:
            cand, cand_cost = None, None
            try:
                p = nx.dijkstra_path(tree, src, dst, weight="cost")
                c = sum(ecost(tree[p[i]][p[i + 1]].get("data", {}))
                        for i in range(len(p) - 1))
                cand, cand_cost = p, c
            except Exception:
                pass
            if dst in direct_dist and (cand_cost is None or direct_dist[dst] < cand_cost):
                cand, cand_cost = direct_paths[dst], direct_dist[dst]
            if cand is None:
                continue
            result[dst] = (cand, cand_cost)
        return result

    best_tree, best_paths, best_total = None, None, None
    for tree in (build_greedy(), build_closure_mst()):
        pmap = dst_paths(tree)
        if len(pmap) < len(dsts):
            continue
        total = sum(c for _, c in pmap.values())
        if best_total is None or total < best_total:
            best_tree, best_paths, best_total = tree, pmap, total

    if best_paths is None:
        best_paths = {d: (direct_paths[d], direct_dist[d])
                      for d in dsts if d in direct_dist}

    # ---- Emit edge lists, reusing the same list across partitions ----
    for dst in dsts:
        if dst not in best_paths:
            continue
        path, _ = best_paths[dst]
        edge_list = []
        for i in range(len(path) - 1):
            s, t = path[i], path[i + 1]
            data = G[s][t] if G.has_edge(s, t) else best_tree[s][t].get("data", {})
            edge_list.append([s, t, data])
        for j in range(bc_topology.num_partitions):
            bc_topology.set_dst_partition_paths(dst, j, list(edge_list))

    return bc_topology


class SingleDstPath(Dict):
    partition: int
    edges: List[List]  # [[src, dst, edge data]]


class BroadCastTopology:
    def __init__(self, src: str, dsts: List[str], num_partitions: int = 4, paths: Dict[str, SingleDstPath] = None):
        self.src = src  # single str
        self.dsts = dsts  # list of strs
        self.num_partitions = num_partitions

        # dict(dst) --> dict(partition) --> list(nx.edges)
        # example: {dst1: {partition1: [src->node1, node1->dst1], partition 2: [src->dst1]}}
        if paths is not None:
            self.paths = paths
            self.set_graph()
        else:
            self.paths = {dst: {str(i): None for i in range(num_partitions)} for dst in dsts}

    def get_paths(self):
        print(f"now the set path is: {self.paths}")
        return self.paths

    def set_num_partitions(self, num_partitions: int):
        self.num_partitions = num_partitions

    def set_dst_partition_paths(self, dst: str, partition: int, paths: List[List]):
        """
        Set paths for partition = partition to reach dst
        """
        partition = str(partition)
        self.paths[dst][partition] = paths

    def append_dst_partition_path(self, dst: str, partition: int, path: List):
        """
        Append path for partition = partition to reach dst
        """
        partition = str(partition)
        if self.paths[dst][partition] is None:
            self.paths[dst][partition] = []
        self.paths[dst][partition].append(path)

def make_nx_graph(cost_path=None, throughput_path=None, num_vms=1):
    """
    Default graph with capacity constraints and cost info
    nodes: regions, edges: links
    per edge:
        throughput: max tput achievable (gbps)
        cost: $/GB
        flow: actual flow (gbps), must be < throughput, default = 0
    """
    # Use relative path from this file's location
    current_dir = os.path.dirname(os.path.abspath(__file__))

    if cost_path is None:
        cost = pd.read_csv(os.path.join(current_dir, "profiles/cost.csv"))
    else:
        cost = pd.read_csv(cost_path)

    if throughput_path is None:
        throughput = pd.read_csv(os.path.join(current_dir, "profiles/throughput.csv"))
    else:
        throughput = pd.read_csv(throughput_path)

    G = nx.DiGraph()
    for _, row in throughput.iterrows():
        if row["src_region"] == row["dst_region"]:
            continue
        G.add_edge(row["src_region"], row["dst_region"], cost=None, throughput=num_vms * row["throughput_sent"] / 1e9)

    for _, row in cost.iterrows():
        if row["src"] in G and row["dest"] in G[row["src"]]:
            G[row["src"]][row["dest"]]["cost"] = row["cost"]

    # some pairs not in the cost grid
    no_cost_pairs = []
    for edge in G.edges.data():
        src, dst = edge[0], edge[1]
        if edge[-1]["cost"] is None:
            no_cost_pairs.append((src, dst))
    print("Unable to get costs for: ", no_cost_pairs)

    return G


